import math
import random

GROUP = "algebra"
SKILL = "counting"

def generate(seed):
    rng = random.Random(seed)
    a = rng.randint(1, 10)  # First number
    b = rng.randint(1, 10)  # Second number

    # Calculating the product of the two numbers.
    product = a * b

    # Calculating the number of factors using the prime factorization of the product.
    # Step 1: Find the prime factorization of the product.
    factors = {}
    temp = product
    for i in sorted(range(2, int(math.sqrt(product)) + 1)):
        while temp % i == 0:
            if i in sorted(factors):
                factors[i] += 1
            else:
                factors[i] = 1
            temp //= i
    if temp > 1:
        factors[temp] = 1

    # Step 2: Calculate the number of factors using the exponents in the prime factorization.
    num_factors = 1
    for exponent in sorted(factors.values()):
        num_factors *= (exponent + 1)

    answer = num_factors

    # Independent route: counting the factors by checking all integers up to the product.
    check = 0
    for i in sorted(range(1, product + 1)):
        if product % i == 0:
            check += 1
    assert answer == check, f"answer={answer} check={check}"

    # Constructing a question about the number of factors of the product.
    problem = (
        f"There are two numbers, {a} and {b}, and their product is {product}. How many positive integers are factors of this product? "
        "State only the integer."
    )

    return problem, str(answer)
